  add("Bangor", "grants", "citizens-advice-bangor", "Citizens Advice — Bangor Advice Centre", "Free advice on benefits, debt, housing and legal issues", "Citizens Advice lists a Bangor centre with initial access usually by phone or web form; in-person visits are appointment-only. Contact to check area eligibility, available advice and appointment options. Advice can help with applications but does not guarantee a benefit award.", "01286 424922", "https://www.citizensadvice.org.uk/wales/about-us/contact-us/local-citizens-advice/0014K000009ESX0QAO/", "Citizens Advice", { address: "Ty Cyfle, 257 High Street, Bangor LL57 1PA", locationLine: "Initial phone/web access · in-person appointments only · contact before visiting" });
  add("Bangor", "grants", "gwynedd-housing-benefit-contact", "Gwynedd Council — housing benefit and council-tax support", "Benefit claim and application assistance", "The council publishes this benefits contact for help with housing-benefit and council-tax reduction claims. Ask about eligibility, evidence and whether your claim should instead go through DWP; awards are subject to assessment and scheme rules.", "01286 682689", "https://www.gwynedd.llyw.cymru/en-gb/council-tax-benefits-and-grants/benefits-and-grants/make-a-benefit-claim", "Gwynedd Council", { email: "budd-daliadau@gwynedd.llyw.cymru", locationLine: "Arfon/Gwynedd residents · call or email for the correct claim route; no award guarantee" });
  add("Bangor", "hotlines", "gwynedd-adult-mental-health-contact", "Gwynedd Adult Mental Health Team — Bangor area contact", "Adult social-care mental-health advice and support route", "Gwynedd’s adult service provides social-work-led support for adults with mental-health needs and their carers. Contact the Bangor area team for guidance and assessment routes; for urgent mental-health help call NHS 111 option 2. This is not an emergency dispatch line.", "01286 682880", "https://www.gwynedd.llyw.cymru/en-gb/social-care-health-and-family-support/adults/mental-health", "Gwynedd Council", { email: "oedolionbangor@gwynedd.llyw.cymru", locationLine: "Bangor/Arfon area · adult support · urgent crisis: NHS 111 option 2" });
  add("Bangor", "hotlines", "nhs-111-mental-health", "NHS 111 Wales — urgent mental-health support", "24/7 urgent mental-health triage", "Call 111 and choose option 2 to speak with a mental-health professional in Wales. For immediate danger or a life-threatening emergency call 999. Triage does not confirm a local appointment or bed.", "111, option 2", "https://www.gov.wales/nhs-111-press-2", "NHS Wales / Welsh Government", { locationLine: "Wales-wide 24/7 urgent mental-health access; clinical triage determines next steps" });

