  add("Llandudno", "peer", "hope-restored-troop-cafe", "Hope Restored — Troop Café", "Hot meal drop-in and connection for people facing homelessness or vulnerability", "Conwy Council lists a hot-meal drop-in at the Coach Park. Contact the provider to confirm the next session and any changes; this is a daytime meal and practical-support route, not accommodation or a guaranteed food parcel.", "07564 991789", "https://www.conwy.gov.uk/en/Resident/Cost-of-Living/Food-Banks.aspx", "Conwy County Borough Council / Hope Restored", { address: "The Coach Park, Mostyn Broadway, Llandudno LL30 1YL", email: "hoperestoredwales@gmail.com", locationLine: "Tuesday and Friday, 8am–1pm listed · confirm before travelling" });
